var i=`0587-mantu`;var t=`world-0587`;var o=`AF`;var a=`south-asia`;var l=4;var g=99;var s={en:`Mantu`,ua:`Манту`};var u={en:`A traditional dish from Afghanistan, centered on all-purpose flour, ground lamb, yellow onion, plain yogurt. A measured home-kitchen version organized by cooking step.`,ua:`Традиційна страва кухні країни Афганістан. Основні складники: пшеничне борошно універсальне, фарш з ягнятини, жовта цибуля, натуральний йогурт. Домашній варіант із кількостями продуктів за етапами приготування.`};var r=[{en:`Mix the dough ingredients, knead until smooth and elastic, then cover and rest for about 18 minutes.`,ua:`Змішайте складники тіста, вимісіть до гладкості й еластичності, накрийте та залиште приблизно на 18 хвилин.`,t:[`mixing`,`kneading`,`resting-dough`],m:18,i:[[`all-purpose-flour`,400,`g`],[`water`,190,`ml`],[`table-salt`,6,`g`]]},{en:`Prepare the filling ingredients: cook or soften any components that require it, let cool, then mix into an even filling.`,ua:`Підготуйте складники начинки: ті, що потребують теплової обробки, приготуйте, охолодіть і змішайте в однорідну начинку.`,t:[`chopping`,`mixing`],m:11,i:[[`ground-lamb`,550,`g`],[`yellow-onion`,220,`g`],[`ground-cumin`,4,`g`]]},{en:`Roll the rested dough thinly, cut rounds, place filling in the center and pinch each dumpling tightly closed.`,ua:`Тонко розкачайте відпочиле тісто, виріжте кружальця, викладіть начинку в центр і ретельно заліпіть краї кожного вареника чи пельменя.`,t:[`rolling-out-dough`,`pinching-dumplings`],m:24,i:[]},{en:`Steam the mantu with space between dumplings until the meat filling is fully cooked; top with garlicky yogurt and tomato sauce.`,ua:`Готуйте манту на парі з проміжками, доки начинка з фаршу повністю не приготується; подавайте з часниковим йогуртом і томатним соусом.`,t:[`steaming`],m:40,i:[]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:6,i:[[`plain-yogurt`,350,`g`],[`garlic`,4,`clove`],[`tomato-passata`,250,`g`]]}];var d={slug:i,id:t,country:`AF`,region:a,servings:4,minutes:99,title:s,text:u,steps:r};export{o as country,d as default,t as id,g as minutes,a as region,l as servings,i as slug,r as steps,u as text,s as title};